"""Every reading and building of dates and times in deskstats lives here.

Nothing in this module reads the machine's clock or time zone, and it imports
nothing from deskstats.  Each function raises ValueError for text it cannot
read and for an unknown unit, method or order.

Some inputs fail in a way that is not a plain ValueError (a year or an hour too
large for a C int, a timestamp too large for the platform).  Those are raised
as errors that are both a ValueError and the original OverflowError or
OSError, so callers that need the old behaviour can still tell them apart.
"""

import functools
import re
from datetime import date, datetime, timedelta, timezone, tzinfo

UTC = timezone.utc

SECONDS = "s"
MILLIS = "ms"

TRUNCATE = "truncate"
NEAREST_EVEN = "nearest_even"

YMD = "ymd"
DMY = "dmy"
MDY = "mdy"

_OFFSET = re.compile(r"([+-])(\d\d):(\d\d)")
_UNITS = (SECONDS, MILLIS)
_METHODS = (TRUNCATE, NEAREST_EVEN)
_ORDERS = (YMD, DMY, MDY)


class _OverflowUnreadable(OverflowError, ValueError):
    pass


class _OSUnreadable(OSError, ValueError):
    pass


def _unreadable(fn):
    """Make the OverflowError and OSError of fn also a ValueError."""

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        try:
            return fn(*args, **kwargs)
        except ValueError:
            raise
        except OverflowError as e:
            raise _OverflowUnreadable(*e.args) from None
        except OSError as e:
            raise _OSUnreadable(*e.args) from None

    return wrapper


def parse_offset(text: str) -> timezone:
    """An offset as the site file writes it: +HH:MM or -HH:MM."""
    m = _OFFSET.fullmatch(text)
    if not m:
        raise ValueError(f"not an offset: {text!r}")
    delta = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return timezone(-delta if m.group(1) == "-" else delta)


@_unreadable
def parse_instant(text: str, naive: tzinfo, layouts: tuple[str, ...] = ()) -> datetime:
    """An ISO 8601 time, or one of the strptime layouts; a time without an offset gets naive."""
    text = text.strip()
    try:
        t = datetime.fromisoformat(text)
    except ValueError:
        for layout in layouts:
            try:
                t = datetime.strptime(text, layout)
                break
            except ValueError:
                pass
        else:
            raise ValueError(f"not a time: {text!r}") from None
    if t.tzinfo is None:
        t = t.replace(tzinfo=naive)
    return t


@_unreadable
def from_epoch(value: str | int | float, unit: str, method: str) -> datetime:
    """Unix time in unit as an aware UTC datetime on a whole second.

    The arithmetic is binary floating point: TRUNCATE is int() of the float
    (toward zero), NEAREST_EVEN is round() of it (halves to the even second).
    """
    if unit not in _UNITS:
        raise ValueError(f"unknown unit: {unit!r}")
    if method not in _METHODS:
        raise ValueError(f"unknown method: {method!r}")
    if isinstance(value, bool) or not isinstance(value, (str, int, float)):
        raise ValueError(f"not a number: {value!r}")
    if method == TRUNCATE:
        number = float(value)
    else:
        number = float(value) if isinstance(value, str) else value
    seconds = number if unit == SECONDS else number / 1000
    whole = int(seconds) if method == TRUNCATE else round(seconds)
    return datetime.fromtimestamp(whole, tz=UTC)


@_unreadable
def parse_day(text: str, order: str) -> date:
    """A day written year first (YMD), day first (DMY: DD/MM/YY) or month first (MDY: MM/DD/YYYY)."""
    if order == YMD:
        return date.fromisoformat(text)
    if order == DMY:
        # A two-digit year is in this century.
        d, m, y = text.split("/")
        year = int(y)
        if year < 100:
            year += 2000
        return date(year, int(m), int(d))
    if order == MDY:
        return datetime.strptime(text, "%m/%d/%Y").date()
    raise ValueError(f"unknown order: {order!r}")


