import unittest
from datetime import date, datetime, timedelta, timezone

from deskstats import timeparse as tp

PLUS1 = timezone(timedelta(hours=1))


class Offsets(unittest.TestCase):
    def test_offsets(self):
        self.assertEqual(tp.parse_offset("+01:00"), PLUS1)
        self.assertEqual(tp.parse_offset("-05:30").utcoffset(None), -timedelta(hours=5, minutes=30))
        self.assertEqual(tp.parse_offset("+01:00").tzname(None), "UTC+01:00")

    def test_bad_offsets(self):
        for text in ["+0100", "", "+1:00", "+01:00\n", " +01:00", "+24:00", "-24:00", "Z"]:
            with self.subTest(text=text), self.assertRaises(ValueError):
                tp.parse_offset(text)


class Instants(unittest.TestCase):
    def test_iso(self):
        self.assertEqual(tp.parse_instant(" 2026-03-02T09:15:02Z ", PLUS1), datetime(2026, 3, 2, 9, 15, 2, tzinfo=tp.UTC))
        self.assertEqual(tp.parse_instant("20260302T091502", tp.UTC), datetime(2026, 3, 2, 9, 15, 2, tzinfo=tp.UTC))

    def test_naive_gets_zone(self):
        t = tp.parse_instant("2026-03-02T09:15:02.5", PLUS1)
        self.assertEqual(t, datetime(2026, 3, 2, 9, 15, 2, 500000, tzinfo=PLUS1))
